import { API, Permission } from "$lib";
import { Session } from "$lib/stores/index.js";
import { error } from "@sveltejs/kit";
import { StatusCodes } from "http-status-codes";

export const load = async ({ url, params }) => {
	if (!(await Session.isValid())) {
		error(StatusCodes.FORBIDDEN);
	}

	const res = await (url.searchParams.get("draft") === "true"
		? API.Manga.GetDraft(params.id)
		: API.Manga.Get(params.id));

	if (res?.status === StatusCodes.OK && res.body) {
		if (!((res.body as Manga & { publication_status?: string }).publication_status === "accepted_pending_projection" && !res.body.relationships) && !Permission.Manga.canUpdate(res.body)) {
			error(StatusCodes.FORBIDDEN);
		}
	} else if (res) error(res.status);
	else error(StatusCodes.INTERNAL_SERVER_ERROR);

	return {
		id: params.id,
		manga: res?.body
	};
};
